/**
 * @summary Validate DSL schema
 */
export type dslValidateResponse201 = {
  data: DslValidationResultDto
  status: 201
}

export type dslValidateResponse401 = {
  data: void
  status: 401
}
    
export type dslValidateResponseSuccess = (dslValidateResponse201) & {
  headers: Headers;
};
export type dslValidateResponseError = (dslValidateResponse401) & {
  headers: Headers;
};

export type dslValidateResponse = (dslValidateResponseSuccess | dslValidateResponseError)

export const getDslValidateUrl = () => {


  

  return `/api/v1/dsl/validate`
}

export const dslValidate = async (dslValidateBody: DslValidateBody, options?: RequestInit): Promise<dslValidateResponse> => {
  
  return customFetch<dslValidateResponse>(getDslValidateUrl(),
  {      
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      dslValidateBody,)
  }
);}




export const getDslValidateMutationOptions = <TError = void,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof dslValidate>>, TError,{data: DslValidateBody}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof dslValidate>>, TError,{data: DslValidateBody}, TContext> => {

const mutationKey = ['dslValidate'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};

      


      const mutationFn: MutationFunction<Awaited<ReturnType<typeof dslValidate>>, {data: DslValidateBody}> = (props) => {
          const {data} = props ?? {};

          return  dslValidate(data,requestOptions)
        }



        


  return  { mutationFn, ...mutationOptions }}

    export type DslValidateMutationResult = NonNullable<Awaited<ReturnType<typeof dslValidate>>>
    export type DslValidateMutationBody = DslValidateBody
    export type DslValidateMutationError = void

    /**
 * @summary Validate DSL schema
 */
export const useDslValidate = <TError = void,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof dslValidate>>, TError,{data: DslValidateBody}, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof dslValidate>>,
        TError,
        {data: DslValidateBody},
        TContext
      > => {
      return useMutation(getDslValidateMutationOptions(options), queryClient);
    }
    